import { type Locale, formatDistance } from "date-fns";
import { de, enUS, es, fr, hu, ja, nl, pt, ptBR, ro, ru, sv, tr, zhCN, zhTW } from "date-fns/locale";
import { TUserLocale } from "@formbricks/types/user";
import { formatDateForDisplay } from "./utils/datetime";

const DEFAULT_LOCALE: TUserLocale = "en-US";
const TIME_SINCE_LOCALES: Record<TUserLocale, Locale> = {
  "de-DE": de,
  "en-US": enUS,
  "es-ES": es,
  "fr-FR": fr,
  "hu-HU": hu,
  "ja-JP": ja,
  "nl-NL": nl,
  "pt-BR": ptBR,
  "pt-PT": pt,
  "ro-RO": ro,
  "ru-RU": ru,
  "sv-SE": sv,
  "tr-TR": tr,
  "zh-Hans-CN": zhCN,
  "zh-Hant-TW": zhTW,
};

const isUserLocale = (locale: string): locale is TUserLocale => Object.hasOwn(TIME_SINCE_LOCALES, locale);

/** Maps locale strings to date-fns locales and falls back to English for unsupported inputs. */
const getLocaleForTimeSince = (locale: string): Locale =>
  isUserLocale(locale) ? TIME_SINCE_LOCALES[locale] : enUS;

export const timeSince = (dateString: string, locale: string = DEFAULT_LOCALE) => {
  const date = new Date(dateString);
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

export const timeSinceDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

export const formatDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDateForDisplay(date, locale, {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

export const getTodaysDateTimeFormatted = (seperator: string) => {
  const date = new Date();
  const formattedDate = date.toISOString().split("T")[0].split("-").join(seperator);
  const formattedTime = date.toTimeString().split(" ")[0].split(":").join(seperator);

  return [formattedDate, formattedTime].join(seperator);
};

export const convertDatesInObject = <T>(obj: T, keysToIgnore?: Set<string>): T => {
  if (obj === null || typeof obj !== "object") {
    return obj; // Return if obj is not an object
  }
  if (Array.isArray(obj)) {
    // Handle arrays by mapping each element through the function
    return obj.map((item) => convertDatesInObject(item, keysToIgnore)) as unknown as T;
  }
  const newObj: Record<string, unknown> = {};
  for (const key in obj) {
    if (keysToIgnore?.has(key)) {
      newObj[key] = obj[key];
      continue;
    }
    if (
      (key === "createdAt" || key === "updatedAt") &&
      typeof obj[key] === "string" &&
      !isNaN(Date.parse(obj[key] as unknown as string))
    ) {
      newObj[key] = new Date(obj[key] as unknown as string);
    } else if (typeof obj[key] === "object" && obj[key] !== null) {
      newObj[key] = convertDatesInObject(obj[key], keysToIgnore);
    } else {
      newObj[key] = obj[key];
    }
  }
  return newObj as T;
};

import type { ReactNode } from "react";

export type TSettingsTableAlign = "left" | "center" | "right";
export type TSettingsTableBreakpoint = "sm" | "md" | "lg";

/**
 * `none` — the table draws no frame, because a `<SettingsCard bodyVariant="flush">` already frames it.
 * `card` — the table draws its own frame, for use outside a settings card.
 */
export type TSettingsTableFrame = "none" | "card";

export type TSettingsTableColumn<TRow> = {
  /** Stable identifier, used as the React key for this column's header and every one of its cells. */
  id: string;
  /** Already-translated header label. `null` renders an empty header cell — pair it with `srLabel`. */
  header: ReactNode;
  cell: (row: TRow, index: number) => ReactNode;
  /**
   * Sets `text-align` on the header cell and every body cell in this column. Defaults to `left`.
   *
   * It moves **inline-level** content, which covers text, badges and `Button`/`Link` (both `inline-flex`).
   * It cannot move a block-level child, so a cell whose content is a wrapper `<div>` — or the skeleton's
   * placeholder bar — is unaffected by it. Declaring it alongside a flex wrapper is therefore inert; pick
   * one and let it be the only alignment source for the column.
   */
  align?: TSettingsTableAlign;
  /** Hides the column below this breakpoint. Applied to the header and body cells together. */
  hideBelow?: TSettingsTableBreakpoint;
  /**
   * Extra classes merged onto the `<th>`.
   *
   * This is where a column's **width** belongs (`w-[22%]`, `w-16`), because the header cell is what
   * sizes the whole column — putting a width on `cellClassName` only affects that one cell. Widths are
   * suggestions rather than commands: the table is `table-auto`, so a long value can still borrow space
   * from a short one, and when a `hideBelow` column drops out the remaining widths rescale.
   */
  headerClassName?: string;
  /**
   * Extra classes merged onto every `<td>` in this column, e.g. `font-medium text-slate-900`.
   *
   * **Do not change the cell's `display` here** — no `flex`, `grid` or `block`. These classes land on the
   * `<td>` itself, so overriding `display` stops it being a table-cell: the shared `align-middle` becomes
   * a no-op (`vertical-align` applies only to inline-level and table-cell boxes) and the browser wraps the
   * cell in an anonymous table-cell that defaults to baseline, so the content sits high in the row. To lay
   * cell content out, put the flex on a wrapper element **inside** `cell` instead. (`hideBelow` exists for
   * the same reason — it uses `table-cell`, not `block`.)
   */
  cellClassName?: string;
  /** Accessible name for a header cell whose `header` is `null` — typically an actions column. */
  srLabel?: string;
  /** Clicks inside this column do not activate the row. Use for action buttons and nested links. */
  stopRowClick?: boolean;
  /** Width of this column's skeleton bar. Defaults to `w-24`. */
  skeletonWidth?: `w-${string}`;
};

type SettingsTableBaseProps<TRow> = {
  columns: TSettingsTableColumn<TRow>[];
  rows: TRow[];
  getRowId: (row: TRow) => string;
  /** Already-translated. Rendered in a full-width cell when there are no rows. */
  emptyMessage: string;
  frame?: TSettingsTableFrame;
  isLoading?: boolean;
  skeletonRows?: number;
  /** Dims the row and blocks its interactions, e.g. while a sibling row's action is in flight. */
  isRowDisabled?: (row: TRow) => boolean;
  /** Non-row content rendered inside the frame, below the table — and outside its horizontal scroll. */
  footer?: ReactNode;
  /** Per-row DOM hooks. Prefer `data-testid` over `id`, which is not unique across rows. */
  getRowProps?: (row: TRow) => { id?: string; "data-testid"?: string };
  bodyProps?: { id?: string };
  id?: string;
  "aria-label"?: string;
  "data-testid"?: string;
  /** Classes for the `<table>` itself. */
  className?: string;
  /** Extra classes for the frame wrapper, e.g. a width constraint. Merged after `frame`. */
  containerClassName?: string;
};

/**
 * `getRowLabel` is required alongside `onRowClick`: the row's activator is a real `<button>`, and a
 * button built out of arbitrary cell content needs an accessible name.
 */
type SettingsTableClickProps<TRow> =
  | { onRowClick?: never; getRowLabel?: never; isRowClickable?: never }
  | {
      onRowClick: (row: TRow) => void;
      getRowLabel: (row: TRow) => string;
      isRowClickable?: (row: TRow) => boolean;
    };

export type TSettingsTableProps<TRow> = SettingsTableBaseProps<TRow> & SettingsTableClickProps<TRow>;

export type TSettingsTableSkeletonProps<TRow> = Pick<
  SettingsTableBaseProps<TRow>,
  "columns" | "frame" | "className" | "containerClassName"
> & { rows?: number };

